// 在Apple环境执行：swiftc OfficePdfTaskGate.swift OfficePdfTaskGateTests.swift -o gate-tests && ./gate-tests
@main struct OfficePdfTaskGateTests {
    static func main() throws {
        var now = 10.0
        let cancelled = OfficePdfTaskGate(deadline: 20, clock: { now })
        assert(cancelled.finish("CANCELLED"))
        assert(!cancelled.finish("TIMEOUT"))
        var published = false
        let cancelledCommit = try cancelled.commit { published = true }
        assert(!cancelledCommit)
        assert(!published && cancelled.snapshot().1)
        let expired = OfficePdfTaskGate(deadline: 20, clock: { now })
        now = 20
        do { _ = try expired.commit { published = true }; fatalError("到期后不应发布") }
        catch let error as OfficePdfNativeError { assert(error.reason == "TIMEOUT") }
        assert(!published)
        let lateCancel = OfficePdfTaskGate(deadline: 20, clock: { now })
        assert(lateCancel.finish("CANCELLED"))
        assert(lateCancel.snapshot().0 == "TIMEOUT" && !lateCancel.snapshot().1)
        now = 10
        let success = OfficePdfTaskGate(deadline: 20, clock: { now })
        let successfulCommit = try success.commit { published = true }
        assert(successfulCommit)
        assert(published && !success.finish("CANCELLED"))
        let raced = OfficePdfTaskGate(deadline: 20, clock: { 10 })
        let group = DispatchGroup()
        let lock = NSLock()
        var winners = 0
        for reason in ["CANCELLED", "TIMEOUT", "NATIVE_FAILURE"] {
            group.enter()
            DispatchQueue.global().async {
                if raced.finish(reason) { lock.lock(); winners += 1; lock.unlock() }
                group.leave()
            }
        }
        group.wait()
        assert(winners == 1)
        print("OfficePdfTaskGate：取消/到期/成功/并发单终态全部通过")
    }
}

