        let folder = URL(fileURLWithPath: CommandLine.arguments[1])
        let raw = try Data(contentsOf: folder.appendingPathComponent("manifest.json"))
        let cases = try JSONSerialization.jsonObject(with: raw) as! [[String: String]]
        for item in cases {
            let expected = item["expected"]!
            let file = item["file"]!
            do {
                let format = try OfficePdfInput.validate(folder.appendingPathComponent(file), declaredFormat: item["declared"]!) {}
                guard format == expected else { fatalError("\(file): 预期 \(expected)，实际 \(format)") }
            } catch let error as OfficePdfNativeError {
                guard error.reason == expected else { fatalError("\(file): 预期 \(expected)，实际 \(error.reason)/\(error.nativeCode)") }
            }
            print("通过：\(file) -> \(expected)")
        }
        var checks = 0
        do {
            _ = try OfficePdfInput.validate(folder.appendingPathComponent("good.docx"), declaredFormat: "") {
                checks += 1
