def function(source, prefix):
    start = source.index(prefix)
    opening = source.index('{', start)
    depth = 0
    for token in re.finditer(r'//[^\n]*|/\*.*?\*/|"(?:\\.|[^"\\])*"|[{}]', source[opening:], re.S):
        if token.group() == '{':
            depth += 1
        elif token.group() == '}':
            depth -= 1
            if depth == 0:
                return source[start:opening + token.end()]
    raise ValueError('无法提取完整函数')


def declaration(source, pattern):
    matches = re.findall(pattern, source, re.S)
    if len(matches) != 1:
        raise ValueError('官方声明不唯一')
    return matches[0]


def run_checked(arguments):
    print('VCL合同命令 argv: ' + repr([str(argument) for argument in arguments]), flush=True)
    result = subprocess.run(arguments, capture_output=True, text=True)
    if result.returncode:
        raise RuntimeError('合同命令返回 ' + str(result.returncode) + '\n' + result.stdout + result.stderr)
    return result


def host_compile_command(compiler):
    command = [compiler, '-std=c++17', '-fno-exceptions', '-fno-rtti']
    if sys.platform == 'darwin':
        # xcrun --find只返回路径；宿主合同链接libc++需要显式macOS SDK，不能沿用iPhoneOS SDK。
        sdk = run_checked(['xcrun', '--sdk', 'macosx', '--show-sdk-path']).stdout.strip()
        if not sdk or not pathlib.Path(sdk).is_dir():
            raise RuntimeError('VCL宿主合同需要现存macOS SDK目录: ' + repr(sdk))
        command.extend(['-isysroot', sdk])
    return command


