def harness(snapshot, patched=True):
    spec = importlib.util.spec_from_file_location('office_pdf_vcl_compat', ROOT / 'build_compat.py')
    compat = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(compat)
    for path, expected in DECLARATION_HASHES.items():
        if hashlib.sha256((snapshot / path).read_bytes()).hexdigest() != expected:
            raise ValueError('官方接口声明快照漂移: ' + path)
    def read(name):
        raw = (snapshot / name).read_bytes()
        if patched:
            raw = compat.transform(raw, name)
        return raw.decode('utf-8')
    ios = read('vcl/ios/salios.cxx')
    quartz = read('vcl/quartz/salvd.cxx')
    copy = function(ios, 'void AquaGraphicsBackend::copyBits(')
    marker = copy.index('std::shared_ptr<SalBitmap> pBitmap;')
    # 直接保留真实fallback分支的全部语句，去掉外侧else和函数闭括号。
    copy_body = copy[marker:copy.rfind('}')].rstrip()
    copy_body = copy_body[:copy_body.rfind('}')]
    header = (snapshot / 'vcl/inc/quartz/salvd.h').read_text(encoding='utf-8')
    base = (snapshot / 'vcl/inc/salvd.hxx').read_text(encoding='utf-8')
    graphics = (snapshot / 'vcl/inc/quartz/salgdi.h').read_text(encoding='utf-8')
    graphics_base = (snapshot / 'vcl/inc/salgdiimpl.hxx').read_text(encoding='utf-8')
    replacements = {
        'BASE_DECL': declaration(base, r'(virtual bool\s+SetSize\([^;]+;)'),
        'DEVICE_DECL': declaration(header, r'(virtual bool\s+SetSize\([^;]+;)'),
        'GRAPHICS_BASE_DECL': declaration(graphics_base, r'(virtual std::shared_ptr<SalBitmap> getBitmap\([^;]+;)'),
        'GRAPHICS_DECL': declaration(graphics, r'(std::shared_ptr<SalBitmap> getBitmap\([^;]+;)'),
        'COPY_BODY': copy_body,
        'SIZE_BODY': function(ios, 'bool AquaSalVirtualDevice::SetSize('),
        'FACTORY_CALL': declaration(quartz, r'(pNew->SetSize\([^;]+;)'),
    }
    value = STUB
    for key in sorted(replacements, key=len, reverse=True):
        value = value.replace(key, replacements[key])
    return value


class VclContractTests(unittest.TestCase):
    def test_real_constructor_and_platform_includes_preserve_backend_selection(self):
        source = os.environ.get('OFFICE_PDF_VCL_SNAPSHOT')
        compiler = os.environ.get('OFFICE_PDF_TEST_CXX') or shutil.which('clang++')
        if not source or not compiler:
            self.skipTest('需要固定VCL快照和现成Clang；CI强制提供')
        snapshot = pathlib.Path(source)
        original, fixed = backend_sections(snapshot, False), backend_sections(snapshot, True)
        with tempfile.TemporaryDirectory() as temporary:
            work = pathlib.Path(temporary)
            def stub(name, content):
                path = work / name
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding='utf-8')
            stub('config_features.h', '// HAVE_FEATURE_SKIA由测试编译参数提供\n')
            stub('vcl/skia/SkiaHelper.hxx', 'namespace SkiaHelper { static bool isVCLSkiaEnabled() { return true; } }\n')
            # 不能让iOS借stub悄悄取得macOS Skia类型。
            stub('skia/osx/gdiimpl.hxx', '#ifndef MACOSX\n#error macOS_Skia_header_on_iOS\n#endif\n'
                 'struct AquaSkiaSalGraphicsImpl : Backend { AquaSkiaSalGraphicsImpl(AquaSalGraphics&, AquaSharedAttributes&) { kind=2; } };\n')
            code = work / 'backend.cxx'
            common = [*host_compile_command(compiler), '-I', str(work)]
            cases = [('original', original), ('fixed', fixed)]
            for name, sections in cases:
                code.write_text(backend_harness(sections), encoding='utf-8')
                for platform, feature in (('IOS', 0), ('IOS', 1), ('MACOSX', 0), ('MACOSX', 1)):
                    arguments = [*common, '-D'+platform, '-DHAVE_FEATURE_SKIA='+str(feature)]
                    preprocessed = subprocess.run([*arguments, '-E', '-P', str(code)], capture_output=True, text=True)
                    # 条件指令可能保留空行；只去除空行，全部非空行（包括token顺序）保持逐字相同。
                    self.assertEqual(preprocessed.returncode == 0, not (name == 'original' and platform == 'IOS'), preprocessed.stderr)
                    preprocessing = '\n'.join(line for line in preprocessed.stdout.splitlines() if line.strip())
                    if platform == 'MACOSX':
                        if name == 'original':
                            if feature == 0: mac_no_skia = preprocessing
                            else: mac_skia = preprocessing
                        else:
                            self.assertEqual(preprocessing, mac_no_skia if feature == 0 else mac_skia)
                    expected_success = platform == 'MACOSX' and feature == 1 or name == 'fixed' and platform == 'IOS'
                    syntax = subprocess.run([*arguments, '-fsyntax-only', str(code)], capture_output=True, text=True)
                    print('VCL后端合同 '+name+'/'+platform+'/skia'+str(feature)+': '+str(syntax.returncode), flush=True)
                    self.assertEqual(syntax.returncode == 0, expected_success, syntax.stderr)
                    if not expected_success:
                        self.assertIn('skia is required on macOS' if feature == 0 else 'macOS_Skia_header_on_iOS', syntax.stderr)
                        continue
                    if platform == 'IOS':
                        self.assertNotIn('AquaSkiaSalGraphicsImpl', preprocessed.stdout)
                        self.assertNotIn('namespace SkiaHelper', preprocessed.stdout)
                    value = backend_harness(sections)
                    variants = [(value, 0),
                                (value.replace('mpFont[i] = nullptr;', '(void)i;'), 43),
                                (value.replace('initWidgetDrawBackends(true);', 'initWidgetDrawBackends(false);'), 44)]
                    for content, expected in variants:
                        code.write_text(content, encoding='utf-8')
                        if sys.platform == 'win32':
                            node = os.environ.get('OFFICE_PDF_TEST_NODE') or shutil.which('node')
                            if not node:
                                self.fail('Windows后端合同需要现成Node')
                            binary = work / 'backend.wasm'
                            compile_args = [*arguments, str(code), '--target=wasm32-unknown-unknown', '-nostdlib',
                                            '-Wl,--no-entry', '-Wl,--export=run_checks', '-o', str(binary)]
                            execute = [node, '-e', 'const fs=require("fs");WebAssembly.instantiate(fs.readFileSync(process.argv[1])).then(x=>process.exit(x.instance.exports.run_checks()));', str(binary)]
                        else:
                            binary = work / 'backend'
                            compile_args = [*arguments, str(code), '-o', str(binary)]
                            execute = [str(binary)]
                        run_checked(compile_args)
                        result = subprocess.run(execute, capture_output=True, text=True)
                        self.assertEqual(result.returncode, expected, result.stderr)
                    code.write_text(value, encoding='utf-8')

    def test_extracted_header_exposes_global_virtual_device_without_transitive_includes(self):
        source = os.environ.get('OFFICE_PDF_VCL_SNAPSHOT')
        compiler = os.environ.get('OFFICE_PDF_TEST_CXX') or shutil.which('clang++')
        if not source or not compiler:
            self.skipTest('需要固定VCL快照和现成Clang；CI强制提供')
        snapshot = pathlib.Path(source)
        original = header_harness(snapshot, False)
        fixed = header_harness(snapshot, True)
        cases = [
            ('original', original, False),
            ('fixed', fixed, True),
            ('removed', fixed.replace('class SalVirtualDevice;', ''), False),
            ('wrong-namespace', fixed.replace('class SalVirtualDevice;', 'namespace wrong { class SalVirtualDevice; }'), False),
            ('signature-drift', fixed.replace('SalVirtualDevice* pVirDev', 'void* pVirDev'), False),
        ]
        with tempfile.TemporaryDirectory() as temporary:
            path = pathlib.Path(temporary) / 'header.cxx'
            for platform in ('IOS', 'MACOSX'):
                for name, content, succeeds in cases:
                    path.write_text(content, encoding='utf-8')
                    command = [*host_compile_command(compiler), '-fsyntax-only', '-D' + platform, str(path)]
                    result = subprocess.run(command, capture_output=True, text=True)
                    print('VCL头声明合同 ' + platform + '/' + name + ': ' + str(result.returncode), flush=True)
                    self.assertEqual(result.returncode == 0, succeeds, result.stdout + result.stderr)
                    if not succeeds:
                        self.assertIn('SalVirtualDevice' if name != 'signature-drift' else 'signature', result.stderr)

    def test_extracted_vcl_interfaces_and_alpha_initialization(self):
        source = os.environ.get('OFFICE_PDF_VCL_SNAPSHOT')
        if not source:
            self.skipTest('未提供固定VCL原始源码和声明快照')
        compiler = os.environ.get('OFFICE_PDF_TEST_CXX') or shutil.which('clang++')
        if not compiler:
            self.skipTest('无现成C++编译器；不能以字符串检查冒充合同编译运行')
        with tempfile.TemporaryDirectory() as temporary:
            work = pathlib.Path(temporary)
            code = work / 'contract.cxx'
            value = harness(pathlib.Path(source))
            mutations = [
                ('/*bWithoutAlpha*/false', '/*bWithoutAlpha*/true'),
                ('bAlphaMaskTransparent ? 0.0 : 1.0', '1.0'),
                ('CGContextRestoreGState(xDrawContext);', '(void)xDrawContext;'),
                ('pNew->SetSize( nDX, nDY, bAlphaMaskTransparent );', 'pNew->SetSize( nDX, nDY, false );'),
            ]
            cases = [value]
            for before, after in mutations:
                self.assertIn(before, value)
                cases.append(value.replace(before, after))
            common = [*host_compile_command(compiler), str(code)]
            if sys.platform == 'win32':
                node = os.environ.get('OFFICE_PDF_TEST_NODE') or shutil.which('node')
                if not node:
                    self.skipTest('Windows合同执行需要现成Node；未安装新依赖')
                binary = work / 'contract.wasm'
                script = 'const fs=require("fs");WebAssembly.instantiate(fs.readFileSync(process.argv[1])).then(x=>process.exit(x.instance.exports.run_checks()));'
                compile_args = [*common, '--target=wasm32-unknown-unknown', '-nostdlib', '-Wl,--no-entry',
                    '-Wl,--export=run_checks', '-o', str(binary)]
                execute_args = [node, '-e', script, str(binary)]
            else:
                binary = work / 'contract'
                compile_args = [*common, '-o', str(binary)]
                execute_args = [str(binary)]
            return_codes = []
            for index, content in enumerate(cases):
                code.write_text(content, encoding='utf-8')
                run_checked(compile_args)
                result = subprocess.run(execute_args, capture_output=True, text=True)
                return_codes.append(result.returncode)
                self.assertEqual(result.returncode, [0, 33, 22, 12, 22][index],
                    '真实抽取代码必须通过；错误alpha/丢恢复/丢透传须命中对应合同: ' + str(index))
            print('VCL抽取合同返回码（正确/丢alpha/错初始化/丢状态恢复/丢参数透传）: ' + str(return_codes))


